}

function siteInfo() {
  let inSite = null;
  let nearCharge = false;
  for (const site of SITES) {
    const d = Math.hypot(hero.state.position.x - site.center.x, hero.state.position.z - site.center.z);
    if (d < site.radius) inSite = site;
