    indicator.classList.add('on');
    window.clearTimeout(indicator._timer);
    indicator._timer = window.setTimeout(() => indicator.classList.remove('on'), 650);
  }
  function damageFlash() {
    const v = el('vignette');
    v.classList.remove('hit');
